head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.SCREN_ID = "ULDSTF15900.xml";     // 호출 화면 아이디 — 공시뷰어 비공개 첨부서류 판단·회사정보 팝업에 넘긴다 (원본 vScrenID)
scwin.POPUP_URL_FORM = "/ui/dis/common/ULDSTF91003.xml";     // 공시제목선택 팝업 (원본 /common/ULDSTF91003.gfm — 경로 가정, 결과서 §10 #4)
scwin.TRST_COM_TYPE = "R";              // 자산운용사 조회구분 (원본 URL 인자 For=R → 명세 ② type)
scwin.LIST_STAT_ETC_TEXT = "기타";        // 상장여부 열: Y·D 가 아닌 값의 표시 (원본 Decode 기본값 — §6.7)
// 원본 : ULDSTF15900.gfm (PF공시검색 — 상장형 수익증권)
/*
 * 화면 동작
 *  - 화면을 열면 공시기간을 "한 달 전 ~ 오늘" 로 두고 자산운용사 콤보를 채운 뒤 바로 조회한다.
 *  - 조건(종목·공시기간·공시제목(서식)·자산운용사)으로 상장형 수익증권(PF) 공시 목록을 조회한다.
 *  - 목록에서 공시제목을 더블클릭하면 공시뷰어, 접수시각은 제출보고서목록, 종목명은 회사정보 확인사항 팝업을 연다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF15900/ULDSTF15900.md (§번호는 이 문서의 절)
 */

// 상장여부 표시·글자색 (원본 grd_Grid 상장여부 열 Decode(LIST_STAT_CD,'Y','상장','D','상장폐지','기타') · color decode — §6.7)
// 검정(#000000)은 기본 글자색이라 class 없음, #FF0033 → red, #009933 → green (base.css 공통 class — 규칙 40)
scwin.LIST_STAT_TEXT = { "Y" : "상장", "D" : "상장폐지" };
scwin.LIST_STAT_CLASS = { "D" : "red" };        // 상장여부 열: 그 밖(기타)은 green
scwin.ISU_NM_CLASS = { "D" : "red", "N" : "green" };     // 종목명 열: Y·그 밖은 기본색

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15900.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 서식코드 숨김 → 기간 콤보·기본 기간(한 달 전 ~ 오늘) → 기간 달력·조회 Enter 키 바인딩 → 자산운용사 콤보 → 목록 조회. (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 서식코드 칸은 숨긴다 — 공시제목 찾기에서 고른 서식코드만 담는다 (원본 showObj(panel_2, false))
    th_FormCd.hide();
    panel_2.hide();

    // 2) 기간선택 콤보와 기본 기간 — 시작 한 달 전, 종료 오늘 (원본 Combo_CBDataSetPeriod · fn_SetCode)
    $c.data.comboCbDataSetPeriod(cmb_PeriodTp);
    const today = $c.date.getServerDateTime("yyyyMMdd");
    dma_search.set("dateS", $c.date.addMonth(today, -1));
    dma_search.set("dateE", today);

    // 3) 기간 달력 선후 검사(규칙 37)·조회 영역 Enter 키(규칙 22)
    $c.date.compareFromToDate(edt_FromDate, edt_ToDate, ["공시기간 시작일", "공시기간 종료일"]);
    $c.win.setEnterKeyEvent(panel_1, scwin.btn_Search_onclick);

    // 4) 자산운용사 콤보를 채운 뒤 조회 (원본은 콤보 Reset 직후 fn_CheckCond — 콤보 값이 비어 있어 결과는 같다)
    await scwin.selectTrstComList();
    await scwin.search();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 버튼 클릭 (조회 영역 Enter 키도 이 핸들러) (원본 btn_Search onclick → fn_CheckCond)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15900.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_Isu_Srh_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기(돋보기) 버튼 클릭 (원본 img_Isu_Srh onclick → JongmokSearch)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_Isu_Srh_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15900.img_Isu_Srh_onclick" });
    }
};

/**
 * @method
 * @name scwin.txb_IsuCd_onblur
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목코드 칸을 비우고 나가면 종목명도 비운다. (원본 txb_IsuCd onblur)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.txb_IsuCd_onblur = function (e) {
    try {
        if ($c.util.isEmpty(dma_search.get("isuCd"))) {
            txb_IsuNm.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15900.txb_IsuCd_onblur" });
    }
};

/**
 * @method
 * @name scwin.img_FindForm_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시제목 찾기(돋보기) 버튼 클릭 (원본 img_FindForm onclick → CreateDialogFrame ULDSTF91003)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_FindForm_onclick = async function (e) {
    try {
        await scwin.openFormPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15900.img_FindForm_onclick" });
    }
};

/**
 * @method
 * @name scwin.txb_FormNm_onviewchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시제목을 직접 고치면 숨은 서식코드를 비운다 — 앞서 팝업에서 고른 서식으로 계속 걸러지지 않게. (§8 #3)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.txb_FormNm_onviewchange = function (info) {
    try {
        dma_search.set("formCd", "");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15900.txb_FormNm_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.cmb_PeriodTp_onviewchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description 기간선택 — 고른 기간으로 시작·종료일을 채운다(종료일 기준 역산, 종료일이 비면 오늘). (원본 cmb_PeriodTp OnSelChange → fn_setFromToDate)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.cmb_PeriodTp_onviewchange = function (info) {
    try {
        // 콤보 값(0~6)은 index 와 같고, 공통 함수는 숫자로 비교한다(문자열 값을 넘기면 어느 기간에도 맞지 않는다)
        $c.stf.setFromToDate(cmb_PeriodTp.getSelectedIndex(), edt_FromDate, edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15900.cmb_PeriodTp_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.grd_Grid_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 목록 셀 더블클릭 — 공시제목·접수시각·종목명 열이면 해당 팝업을 연다. (원본 grd_Grid OnDblClick)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_Grid_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.openRowPopup(rowIndex, columnId);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15900.grd_Grid_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Excel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 엑셀다운로드 버튼 클릭 (원본 btn_Excel onclick)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Excel_onclick = async function (e) {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15900.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectTrstComList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 자산운용사 콤보 목록 조회 — 콤보는 itemset 으로 dlt_trstComList 에 바인딩돼 있다. (원본 fn_SetCode dts_TrstComList listTrstComPF — §5.2)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectTrstComList = async function () {
    dma_trstComReq.set("type", scwin.TRST_COM_TYPE);

    // TODO: 명세 ② 의 경로가 ① 목록 조회와 같다(명세 복사 오류로 보임) — 명세대로 부르고 확정 경로를 받으면 고친다 (§10 #1)
    const sbmOptions = {
        id : "sbm_selectTrstComList",
        method : "get",
        action : "/api/discls/dsclsrch/detailed-dscl/pf/select-list",
        ref : "dma_trstComReq",
        target : "dlt_trstComList=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result.responseJSON?.success === true;    // 실패 안내는 공통 오류 핸들러
};

/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 30
 * @description PF 공시 목록 조회 — 조회조건은 dma_search 에 바인딩돼 있다. 건수를 적는다. (원본 fn_Search dts_DsclList listPFDsclSrch — §5.1)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectList = async function () {
    // TODO: 자산운용사(trstComIsurCd)는 명세 requestData 에 없지만 원본 TRST_COM_ISUR_CD 조건이라 함께 보낸다 (§10 #2)
    const sbmOptions = {
        id : "sbm_selectList",
        method : "get",
        action : "/api/discls/dsclsrch/detailed-dscl/pf/select-list",
        ref : "dma_search",
        target : "dlt_list=body",
        gridview : "grd_Grid",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;    // 실패 안내는 공통 오류 핸들러(원본 OnLoadError → alert_error)

    panel_page.setValue(dlt_list.getRowCount());    // 원본 FillGridHeaderTotalCnt(rowcount, panel_page)
    return true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 — 조회조건을 검사하고 통과하면 목록을 조회한다. (원본 fn_CheckCond — §6.1)
 * @returns
 * @hidden N
 */
scwin.search = async function () {
    if (!(await scwin.validateSearch())) return;
    await scwin.selectList();
};

/**
 * @method
 * @name scwin.validateSearch
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회조건 검사 — 공시기간 시작·종료일이 8자리인지, 시작일이 종료일보다 늦지 않은지. (원본 fn_CheckCond · compareFromToDate2 — §6.1)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.validateSearch = async function () {
    const dateS = String(dma_search.get("dateS") ?? "");
    const dateE = String(dma_search.get("dateE") ?? "");

    if (dateS.length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return false;
    }
    if (dateE.length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return false;
    }
    if (Number(dateS) > Number(dateE)) {
        await $c.win.alert("검색시작일을  검색종료일 이전으로 선택하세요.");
        edt_FromDate.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상장종목찾기(ULDSTF92017) — 상장형 수익증권(PF) 종목을 골라 종목코드·명에 채운다. 취소·닫기면 그대로 둔다. 조회는 하지 않는다(원본과 같음).
 * (원본 JongmokSearch(txb_IsuCd, txb_IsuNm, SECUGRP_ID_PF, js_market, "A") — §6.2)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    // TODO: 원본은 stockSearch.js JongmokSearch(ULDCOM00003 종목검색창)였다. 전환된 종목 팝업 계약이 있는 92017 로 연다 (§10 #3)
    const result = await $c.lc.popFindIsu($c.lc.glb.SECUGRP_ID_PF);

    // 취소·닫기(X)도 { isCloseButtonClick } 객체가 온다 → 종목코드로 판정한다
    if ($c.util.isEmpty(result?.isuCd)) return;

    dma_search.set("isuCd", result.isuCd);
    txb_IsuNm.setValue(result.isuKorNm ?? "");
};

/**
 * @method
 * @name scwin.openFormPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시제목선택(ULDSTF91003) — 고른 서식의 서식코드·서식명을 조회조건에 채운다. 취소·닫기면 그대로 둔다.
 * (원본 CreateDialogFrame("FORMLIST", "/common/ULDSTF91003.gfm", …) — 팝업이 opener 의 txb_FormCd·txb_FormNm 에 직접 넣었다, §6.3·§6.5)
 * @returns
 * @hidden N
 */
scwin.openFormPopup = async function () {
    const options = {
        id : "ULDSTF91003",
        popupName : "공시제목선택",
        width : 690,
        height : 570,
        type : "pageFramePopup"
    };

    // TODO: 91003 은 미전환 — 경로·반환 키({ formCd, formKorNm })는 제안이다 (§10 #4)
    const result = await $c.win.openPopup(scwin.POPUP_URL_FORM, options, {});
    if ($c.util.isEmpty(result?.formCd)) return;    // 취소·닫기(X) — { isCloseButtonClick }

    dma_search.set("formCd", result.formCd);
    dma_search.set("formNm", result.formKorNm ?? "");
};

/**
 * @method
 * @name scwin.openRowPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 더블클릭한 열에 따라 팝업을 연다 — 공시제목: 공시뷰어, 접수시각: 제출보고서목록, 종목명: 회사정보 확인사항. 그 밖의 열은 아무것도 하지 않는다.
 * (원본 grd_Grid OnDblClick + fn_setContnId — §6.4)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.openRowPopup = async function (rowIndex, columnId) {
    const acptNo = dlt_list.getCellData(rowIndex, "acptNo");
    const isurCd = dlt_list.getCellData(rowIndex, "isurCd");

    if (columnId === "docTitle") {
        // 2017-11-28 비공개 첨부서류는 볼 수 없다 — 호출 화면 아이디로 뷰어가 판단한다 (원본 fn_OpenDisclViewer(gAcptNo, "R", vScrenID))
        await $c.stf.openDisclViewer(acptNo, "R", scwin.SCREN_ID);
    } else if (columnId === "acptDdtm") {
        // 원본 fn_OpenDisclAllList — 전역 gIsurCd 대신 data 로 넘긴다
        $c.stf.openDisclAllList({ isurCd : isurCd, isDigitalYn : false });
    } else if (columnId === "isuKorAbbrv") {
        // 원본 fn_PopupCorpInfo — 전역 gIsurCd 대신 data 로 넘긴다
        $c.stf.openPopupCorpInfo({ screnID : scwin.SCREN_ID, isurCd : isurCd });
    }
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 30
 * @description 목록을 엑셀로 내려받는다. 0건 안내는 공통 함수가 한다. (원본 GridToExcel("PF공시 목록", "", "8"), doLogSave 삭제 — §6.6)
 * @returns
 * @hidden N
 */
scwin.excelDown = async function () {
    await $c.data.downloadGridViewExcel(grd_Grid, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42)
        fileName : $c.win.getProgramId() + "_PF공시목록_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "sheet1"
    });
};

/**
 * @method
 * @name scwin.fmtListStatCd
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상장여부 열 customFormatter — 상장상태코드를 상장·상장폐지·기타로 표시하고, 상장폐지는 red, 기타는 green 글자색을 그리드 내장 API 로 붙인다.
 * 동기 함수 — async 금지(규칙 43). (원본 Decode(LIST_STAT_CD,'Y','상장','D','상장폐지','기타') · color decode — §6.7)
 * @param {String} data 원본 값(상장상태코드)
 * @param {String} formattedData 표시 형식이 적용된 값
 * @param {Number} rowIndex 화면 행 번호 — setCellClass 에 그대로 넘긴다
 * @param {Number} colIndex 컬럼 번호
 * @returns {String} 셀에 표시할 값(HTML 없음)
 * @hidden N
 */
scwin.fmtListStatCd = function (data, formattedData, rowIndex, colIndex) {
    const code = String(data ?? "");
    const cls = (code === "Y") ? "" : (scwin.LIST_STAT_CLASS[code] ?? "green");
    if (cls) {
        this.setCellClass(rowIndex, colIndex, cls);
    } else {
        this.removeCellClass(rowIndex, colIndex);
    }
    return scwin.LIST_STAT_TEXT[code] ?? scwin.LIST_STAT_ETC_TEXT;
};

/**
 * @method
 * @name scwin.fmtIsuKorAbbrv
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목명 열 customFormatter — 값은 그대로 두고, 상장상태가 상장폐지면 red, 미상장(N)이면 green 글자색을 붙인다.
 * 동기 함수 — async 금지(규칙 43). (원본 ISU_KOR_ABBRV color Decode(LIST_STAT_CD,'Y','#000000','D','#FF0033','N','#009933') — §6.7)
 * @param {String} data 원본 값(종목약명)
 * @param {String} formattedData 표시 형식이 적용된 값
 * @param {Number} rowIndex 화면 행 번호 — 같은 행 상장상태는 그리드 기준으로 읽는다
 * @param {Number} colIndex 컬럼 번호
 * @returns {String} 셀에 표시할 값(HTML 없음)
 * @hidden N
 */
scwin.fmtIsuKorAbbrv = function (data, formattedData, rowIndex, colIndex) {
    const cls = scwin.ISU_NM_CLASS[String(this.getCellData(rowIndex, "listStatCd") ?? "")];
    if (cls) {
        this.setCellClass(rowIndex, colIndex, cls);
    } else {
        this.removeCellClass(rowIndex, colIndex);
    }
    return formattedData;
};

/**
 * @method
 * @name scwin.fmtDdtm
 * @author Inswave
 * @date 2026. 10. 30
 * @description 접수·처리·배포시각 열 customFormatter — yyyyMMddHHmmss 를 yyyy-MM-dd HH:mm 으로 표시한다(원본 mask XXXX-XX-XX XX:XX). 12자리 미만이면 그대로. (§6.7)
 * @param {String} data 원본 값(일시 14자리)
 * @param {String} formattedData 표시 형식이 적용된 값
 * @param {Number} rowIndex 화면 행 번호
 * @param {Number} colIndex 컬럼 번호
 * @returns {String} 셀에 표시할 값
 * @hidden N
 */
scwin.fmtDdtm = function (data, formattedData, rowIndex, colIndex) {
    const value = String(data ?? "");
    if (value.length < 12) return value;
    return value.substring(0, 4) + "-" + value.substring(4, 6) + "-" + value.substring(6, 8) + " " + value.substring(8, 10) + ":" + value.substring(10, 12);
};
